import React, { useState } from 'react';

const navBarStyles = `
.custom-navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.07);
  z-index: 100;
  display: flex;
  align-items: center;
  height: 64px;
  padding: 0 32px;
}
.custom-navbar .navbar-brand {
  display: flex;
  align-items: center;
  margin-right: 32px;
  text-decoration: none;
}
.custom-navbar .logo {
  height: 40px;
  margin-right: 10px;
}
.custom-navbar .nav {
  display: flex;
  gap: 24px;
  margin: 0;
  padding: 0;
  list-style: none;
  height: 100%;
}
.custom-navbar .nav-link {
  color: #222;
  text-decoration: none;
  font-weight: 500;
  padding: 8px 12px 4px 12px;
  border-radius: 4px 4px 0 0;
  transition: background 0.2s, color 0.2s;
  position: relative;
  display: flex;
  align-items: center;
  height: 100%;
}
.custom-navbar .nav-link.active {
  color: #002147;
}
.custom-navbar .nav-link.active::after {
  content: '';
  display: block;
  position: absolute;
  left: 0;
  bottom: -8px;
  width: 100%;
  height: 4px;
  background: #1976d2;
  border-radius: 2px 2px 0 0;
}
.custom-navbar .nav-link:hover {
  background: #f2f2f2;
  color: #002147;
}
.custom-navbar .langmenu,
.custom-navbar .usermenu-container {
  margin-left: 24px;
}
.custom-navbar .login a {
  color: #002147;
  font-weight: 600;
  text-decoration: none;
  padding: 8px 16px;
  border-radius: 4px;
  background: #f2f2f2;
  transition: background 0.2s;
}
.custom-navbar .login a:hover {
  background: #ffcc00;
  color: #222;
  right: 10px;
}
@media (max-width: 900px) {
  .custom-navbar {
    flex-direction: column;
    height: auto;
    padding: 8px;
  }
  .custom-navbar .nav {
    flex-direction: column;
    gap: 8px;
  }
  .custom-navbar .nav-link.active::after {
    display: none;
  }
}
`;

const NavBar = () => {
  const [active, setActive] = useState('odabir-teme');

  React.useEffect(() => {
    if (!document.getElementById('custom-navbar-styles')) {
      const style = document.createElement('style');
      style.id = 'custom-navbar-styles';
      style.innerHTML = navBarStyles;
      document.head.appendChild(style);
    }
  }, []);

  return (
    <nav className="custom-navbar">
      <a href="#" className="navbar-brand">
        <img
          src="https://eucenje.sum.ba/moodle/pluginfile.php/1/core_admin/logocompact/300x300/1746443490/Logo%20sumarum.png"
          className="logo"
          alt="SUMARUM"
        />
      </a>
      <ul className="nav">
        <li>
          <a
            className={`nav-link${active === 'odabir-teme' ? ' active' : ''}`}
            href="#"
            onClick={() => setActive('odabir-teme')}
          >
            Odabir Teme
          </a>
        </li>
        <li>
          <a
            className={`nav-link${active === 'druga-stavka' ? ' active' : ''}`}
            href="#"
            onClick={() => setActive('druga-stavka')}
          >
            Druga Stavka
          </a>
        </li>
      </ul>
      <div style={{ flex: 1 }} />
      <div className="langmenu">
        <div className="dropdown show">
          <a href="#" className="btn dropdown-toggle" aria-haspopup="true">
            <span className="langbutton">Hrvatski ‎(hr)‎</span>
          </a>
          <div className="dropdown-menu dropdown-menu-right">
            <a href="https://eucenje.sum.ba/moodle/?lang=en" className="dropdown-item" lang="en">
              English ‎(en)‎
            </a>
            <a href="#" className="dropdown-item" aria-current="true">
              Hrvatski ‎(hr)‎
            </a>
          </div>
        </div>
      </div>
      <div className="usermenu-container">
        <span className="login">
          <a href="https://eucenje.sum.ba/moodle/login/index.php">Prijava</a>
        </span>
      </div>
    </nav>
  );
};

export default NavBar;
